  ('4fd0b7cf-d2c0-48af-b1f5-6cdd16ad9ad4', '8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', '08fb2149-399c-48e2-954e-d64a0e955ad5', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$[She hands them each a bowl of freshly cooked phirni. Jotting down facts, both Deepti and Rosy thank Grandma and exit.]$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-52-170Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
